// 集計期間の設定(前日)
const today = new Date();
const yesterday = new Date(today);
yesterday.setDate(yesterday.getDate() - 1);
const period_start = yesterday.toISOString().split('T')[0];
const period_end = today.toISOString().split('T')[0];
return [{ json: {
  experiment_id: 'daily-metrics',
  period_start,
  period_end,
  execution_date: today.toISOString()
} }];

// WordPress REST API: 将来のPV/クリック自動取得に備えた接続準備(現状は未使用・手入力はGoogle Sheetsで代替)
const cfg = $input.first().json;
const wp_url = $env.WORDPRESS_BLOG_URL ?? 'https://example.com';
const wp_user = $env.WORDPRESS_API_USER ?? '';
const wp_pass = $env.WORDPRESS_API_PASS ?? '';
const auth = Buffer.from(wp_user + ':' + wp_pass).toString('base64');
return [{ json: { ...cfg, wp_url, wp_auth: auth, note: 'WordPress接続準備完了(未使用・Jetpack Stats API等の実装待ち)' } }];

// API 応答をパース
const gumroad_result = $('API: Gumroad').first().json;
const brain_result = $('API: Brain').first().json;

let gumroad_sales = null, gumroad_error = null;
let brain_sales = null, brain_error = null;

if (gumroad_result?.error) {
  gumroad_error = 'gumroad_api_error';
} else if (gumroad_result?.products) {
  gumroad_sales = gumroad_result.products.reduce((s,p) => s + (p.sales_count || 0), 0) || 0;
} else {
  gumroad_error = 'gumroad_parse_failed';
}

if (brain_result?.error) {
  brain_error = 'brain_api_error';
} else if (brain_result?.sales) {
  brain_sales = brain_result.sales || 0;
} else {
  brain_error = 'brain_parse_failed';
}

const cfg = $('Config Period').first().json;
return [{ json: { ...cfg, gumroad_sales, gumroad_error, brain_sales, brain_error } }];

// Google Sheets(手入力分)を period_start の日付行でマッチングして取り込む。
// 該当行が無い場合は捏造せず0+未取得フラグを立てる。
const apiData = $input.first().json;
const cfg = $('Config Period').first().json;

function findRow(nodeName) {
  try {
    const rows = $(nodeName).all().map(i => i.json);
    return rows.find(r => String(r.date) === cfg.period_start) ?? null;
  } catch (e) {
    return null;
  }
}

const noteRow = findRow('Sheets: note_data');
const threadsRow = findRow('Sheets: threads_data');
const wordpressRow = findRow('Sheets: wordpress_data');
const rakutenRow = findRow('Sheets: rakuten_data');
const amazonRow = findRow('Sheets: amazon_data');

const sheet_data = {
  note_sales: Number(noteRow?.sales ?? 0),
  note_views: Number(noteRow?.views ?? 0),
  threads_impressions: Number(threadsRow?.impressions ?? 0),
  threads_clicks: Number(threadsRow?.clicks ?? 0),
  wordpress_pv: Number(wordpressRow?.pv ?? 0),
  wordpress_clicks: Number(wordpressRow?.clicks ?? 0),
  rakuten_sales: Number(rakutenRow?.sales ?? 0),
  rakuten_views: Number(rakutenRow?.views ?? 0),
  amazon_clicks: Number(amazonRow?.clicks ?? 0),
  amazon_conversions: Number(amazonRow?.conversions ?? 0),
  // Google Sheetsに費用/稼働時間の入力欄が未整備のため暫定0固定(既知の制約。TASK-048参照)
  cost_anthropic: 0,
  cost_browser: 0,
  owner_hours: 0,
  sheets_rows_found: {
    note: !!noteRow,
    threads: !!threadsRow,
    wordpress: !!wordpressRow,
    rakuten: !!rakutenRow,
    amazon: !!amazonRow
  }
};

return [{ json: { ...apiData, ...sheet_data } }];

// 全媒体のデータを集約・整形
const d = $input.first().json;

const platform_breakdown = {
  gumroad: { sales: d.gumroad_sales || 0, error: d.gumroad_error },
  brain: { sales: d.brain_sales || 0, error: d.brain_error },
  note: { sales: d.note_sales || 0, views: d.note_views || 0 },
  threads: { impressions: d.threads_impressions || 0, clicks: d.threads_clicks || 0 },
  wordpress: { pv: d.wordpress_pv || 0, clicks: d.wordpress_clicks || 0 },
  rakuten: { sales: d.rakuten_sales || 0, views: d.rakuten_views || 0 },
  amazon: { clicks: d.amazon_clicks || 0, conversions: d.amazon_conversions || 0 }
};

const total_revenue = (d.gumroad_sales||0) + (d.brain_sales||0) + (d.note_sales||0) + (d.rakuten_sales||0) + (d.amazon_conversions||0);
const total_cost = (d.cost_anthropic||0) + (d.cost_browser||0);
const gross_profit = total_revenue - total_cost;
const kpi = d.owner_hours > 0 ? +(gross_profit / d.owner_hours).toFixed(1) : null;

return [{ json: {
  experiment_id: d.experiment_id,
  period: d.period_start + ' 〜 ' + d.period_end,
  platform_breakdown,
  summary: {
    total_revenue,
    total_cost,
    gross_profit,
    owner_hours: d.owner_hours,
    kpi_profit_per_hour: kpi
  },
  errors: { gumroad: d.gumroad_error, brain: d.brain_error },
  sheets_rows_found: d.sheets_rows_found,
  state: 'READY_FOR_ANALYSIS',
  data_completeness: 'INTEGRATED'
} }];

// Slack 通知用テキストを整形
const d = $input.first().json;
const pb = d.platform_breakdown;
const s = d.summary;

const lines = [
  '【RIO メトリクス統合】' + d.period,
  '',
  '📊 媒体別売上:',
  `  Gumroad: ${pb.gumroad.sales}円 ${pb.gumroad.error ? '⚠️ ' + pb.gumroad.error : ''}`,
  `  Brain: ${pb.brain.sales}円 ${pb.brain.error ? '⚠️ ' + pb.brain.error : ''}`,
  `  note: ${pb.note.sales}円 (${pb.note.views} views)`,
  `  楽天room: ${pb.rakuten.sales}円 (${pb.rakuten.views} views)`,
  `  Amazon: ${pb.amazon.conversions} 成果`,
  '',
  '📈 コンテンツ指標:',
  `  Threads: ${pb.threads.impressions} imp, ${pb.threads.clicks} clicks`,
  `  WordPress: ${pb.wordpress.pv} PV, ${pb.wordpress.clicks} clicks`,
  '',
  '💰 財務:',
  `  売上合計: ${s.total_revenue}円 | 費用: ${s.total_cost}円 | 粗利: ${s.gross_profit}円`,
  `  KPI: ${s.kpi_profit_per_hour ?? 'N/A'} 円/時`
];

return [{ json: { ...d, notification_text: lines.join('\n') } }];
